CREATE TABLE companies (id text PRIMARY KEY, name text NOT NULL, settings jsonb NOT NULL DEFAULT '{}');
CREATE TABLE users (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','manager','estimator','operator')));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE customers (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), name text NOT NULL, contact text NOT NULL, email text NOT NULL, phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', sector text NOT NULL DEFAULT 'Commercial', terms integer NOT NULL DEFAULT 30 CHECK(terms>=0), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,company_id));
CREATE TABLE quotes (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), number text NOT NULL UNIQUE, customer_id text NOT NULL, title text NOT NULL, status text NOT NULL CHECK(status IN ('Draft','Sent','Accepted','Declined')), revision integer NOT NULL DEFAULT 1, due_date date NOT NULL, valid_until date NOT NULL, notes text NOT NULL DEFAULT '', total_cents integer NOT NULL CHECK(total_cents>=0), cost_cents integer NOT NULL CHECK(cost_cents>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,company_id), FOREIGN KEY(customer_id,company_id) REFERENCES customers(id,company_id));
CREATE TABLE quote_lines (id text PRIMARY KEY, quote_id text NOT NULL REFERENCES quotes(id), position integer NOT NULL, snapshot jsonb NOT NULL);
CREATE TABLE orders (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), number text NOT NULL UNIQUE, customer_id text NOT NULL, quote_id text UNIQUE, title text NOT NULL, status text NOT NULL CHECK(status IN ('Confirmed','In production','Ready','Completed','Cancelled')), due_date date NOT NULL, site text NOT NULL DEFAULT '', po_number text NOT NULL DEFAULT '', total_cents integer NOT NULL, deposit_paid boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,company_id), FOREIGN KEY(customer_id,company_id) REFERENCES customers(id,company_id), FOREIGN KEY(quote_id,company_id) REFERENCES quotes(id,company_id));
CREATE TABLE order_lines (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), description text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), snapshot jsonb NOT NULL);
CREATE TABLE machines (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), name text NOT NULL, kind text NOT NULL, department text NOT NULL, state text NOT NULL CHECK(state IN ('Available','Running','Maintenance','Offline')), hourly_rate numeric(10,2) NOT NULL CHECK(hourly_rate>=0), capabilities text NOT NULL, notes text NOT NULL DEFAULT '', UNIQUE(id,company_id));
CREATE TABLE jobs (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), number text NOT NULL UNIQUE, order_id text NOT NULL, order_line_id text NOT NULL UNIQUE REFERENCES order_lines(id), customer_id text NOT NULL, title text NOT NULL, department text NOT NULL, state text NOT NULL CHECK(state IN ('Queued','Ready','Running','Paused','Blocked','Complete','Cancelled')), priority text NOT NULL CHECK(priority IN ('Normal','High','Urgent')), due_date date NOT NULL, machine_id text, assignee text NOT NULL DEFAULT '', ordered integer NOT NULL CHECK(ordered>0), produced integer NOT NULL DEFAULT 0 CHECK(produced>=0), rejected integer NOT NULL DEFAULT 0 CHECK(rejected>=0), delivered integer NOT NULL DEFAULT 0 CHECK(delivered>=0), invoiced integer NOT NULL DEFAULT 0 CHECK(invoiced>=0), area numeric(12,2) NOT NULL DEFAULT 0, artwork_approved boolean NOT NULL DEFAULT false, material_ready boolean NOT NULL DEFAULT true, approved_version integer, artwork_version integer NOT NULL DEFAULT 1, notes text NOT NULL DEFAULT '', blocker text NOT NULL DEFAULT '', elapsed_seconds integer NOT NULL DEFAULT 0, started_at timestamptz, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(order_id,company_id) REFERENCES orders(id,company_id), FOREIGN KEY(customer_id,company_id) REFERENCES customers(id,company_id), FOREIGN KEY(machine_id,company_id) REFERENCES machines(id,company_id), CHECK(produced<=ordered), CHECK(delivered<=produced), CHECK(invoiced<=ordered));
CREATE TABLE job_events (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), job_id text NOT NULL REFERENCES jobs(id), actor text NOT NULL, action text NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), actor text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, action text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_company_queue ON jobs(company_id,department,state);
CREATE INDEX orders_company_due ON orders(company_id,due_date);
CREATE INDEX quotes_company_customer ON quotes(company_id,customer_id);
CREATE INDEX events_job ON job_events(job_id,created_at DESC);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE SEQUENCE quote_number_seq START 1050;
CREATE SEQUENCE order_number_seq START 2050;
CREATE SEQUENCE job_number_seq START 3050;
